import { Upload, UploadProps } from "@arco-design/web-react";
import { action, computed, observable, makeObservable } from "mobx";
import _ from 'lodash';

export default class Store {
    list: UploadProps['fileList'] = [];

    constructor() {
        makeObservable(this, {
            list: observable,
            value: computed,
            setList: action
        });

        makeObservable(this);
    }

    get value(): string[] {

        return this.list.map((o) => o.url).filter((url) => url);
    }

    setList = (list: UploadProps['fileList']) => {
        this.list = list.map(o => {
            if(!o.url && o.response){
                const res: any = o.response || {};
                if(res.code === 0 && res.data){
                    _.assign(o, res.data);
                }else {
                    o.status = 'error';
                }
            }else if(o.status === 'uploading'){
                o.percent = 50;
            }

            return o;
        });
    };
}