/**
 * 方便用户图片上传，主要改动点
 * @tip1 自定义 value 接管了 list ( 为了 form 表单接管状态方便 )
 * @tip2 默认value 是string 类型，如果想要上传多个图片 可以使用 multipleChoice
 */
export interface UploaderProps extends Omit<UploadProps, 'onChange'> {
  value?: string | string[];
  store?: Store;
  // 是否开启多选
  multipleChoice?: boolean;
  // 是否裁剪图片
  cropped?: boolean;
  children?: ReactNode;
  onChange?: (value: string | string[], list: any | any[]) => void;
}



async function _getCroppedImg(url, pixelCrop, rotation = 0) {
  const image: any = await new Promise((resolve, reject) => {
    const image = new Image();
    image.addEventListener('load', () => resolve(image));
    image.addEventListener('error', (error) => reject(error));
    image.src = url;
  });
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  if (!ctx || !image) {
    return null;
  }

  const imageSize = 2 * ((Math.max(image.width, image.height) / 2) * Math.sqrt(2));
  canvas.width = imageSize;
  canvas.height = imageSize;

  if (rotation) {
    ctx.translate(imageSize / 2, imageSize / 2);
    ctx.rotate((rotation * Math.PI) / 180);
    ctx.translate(-imageSize / 2, -imageSize / 2);
  }

  ctx.drawImage(image, imageSize / 2 - image.width / 2, imageSize / 2 - image.height / 2);
  const data = ctx.getImageData(0, 0, imageSize, imageSize);
  canvas.width = pixelCrop.width;
  canvas.height = pixelCrop.height;
  ctx.putImageData(
    data,
    Math.round(0 - imageSize / 2 + image.width * 0.5 - pixelCrop.x),
    Math.round(0 - imageSize / 2 + image.height * 0.5 - pixelCrop.y)
  );
  return new Promise((resolve) => {
    canvas.toBlob((blob) => {
      resolve(blob);
    });
  });
} 


// 裁剪组件
const Cropper = (props) => {
  const { file, url } = props;
  const [crop, setCrop] = useState({
    x: 0,
    y: 0,
  });
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [sssss, setCroppedAreaPixels] = useState(undefined)
  const [key, setKey] = useState<any>();

  useEffect(() => {
    // 这边不加盐吃，截图区域会对不上
    setTimeout(() => setKey(Date.now()),200)
  },[])

  return (
    <div>
      <div
        style={{
          width: '100%',
          height: "280px",
          position: 'relative',
        }}
      >
        {key && (
          <EasyCropper
            key={key}
            style={{
              containerStyle: {
                width: '100%',
                height: "280px",
              },
            }}
            aspect={4 / 4}
            image={url}
            crop={crop}
            zoom={zoom}
            rotation={rotation}
            onRotationChange={setRotation}
            onCropComplete={(_, croppedAreaPixels) => {
              setCroppedAreaPixels(croppedAreaPixels)
            }}
            onCropChange={setCrop}
            onZoomChange={setZoom}
          />
        )}
      </div>
      <Grid.Row justify='space-between' style={{ marginTop: 20, marginBottom: 20 }}>
        <Grid.Row
          style={{
            flex: 1,
            marginLeft: 12,
            marginRight: 12,
          }}
        >
          <IconMinus
            style={{ marginRight: 10 }}
            onClick={() => {
              setZoom(Math.max(1, zoom - 0.1));
            }}
          />
          <Slider
            style={{ flex: 1 }}
            step={0.1}
            value={zoom}
            onChange={(v: any) => {
              setZoom(v);
            }}
            min={0.8}
            max={3}
          />
          <IconPlus
            style={{ marginLeft: 10 }}
            onClick={() => {
              setZoom(Math.min(3, zoom + 0.1));
            }}
          />
        </Grid.Row>
        <IconRotateLeft
          onClick={() => {
            setRotation(rotation - 90);
          }}
        />
      </Grid.Row>

      <Grid.Row justify='end'>
        <Button onClick={props.onCancel} style={{ marginRight: 20 }}>
          取消
        </Button>
        <Button
          type='primary'
          onClick={async () => {
            const blob: any = await _getCroppedImg(url || '', sssss, rotation);

            if (blob) {
              const newFile = new File([blob], file.name || 'image', {
                type: file.type || 'image/*',
              });
              props.onOk(newFile);
            }
          }}
        >
          确定
        </Button>
      </Grid.Row>
    </div>
  );
};




const UploadImg = ({ value, onChange, multipleChoice, store:uStore, ...props }: UploaderProps) => {

  const [store] = useState(() => uStore || new Store())
  return useObserver(() => {

    const values = useMemo(() => {
      if(!value) return [];
      const values = Array.isArray(value)? value : [value];
      return values;
    },[value])

    useEffect(() => {
      if(!values.length) {
        store.setList([]);
      };
      const map = new Map(store.list.filter((o) => o.url).map((o) => [o.url, o]));
      const list = values.filter((url) => !map.has(url));
      if(list.length){
        store.setList(store.list.concat(list.map((url) => {
          return {
            uid: Math.random().toString(32).slice(2),
            url: url,
            status: 'done'
          }
        })))
      }
    },[values])


    const beforeUpload = useMemo(() => {
      
      return (file) => {
        return new Promise((resolve) => {
          const url = URL.createObjectURL(file);
          const modal = Modal.confirm({
              title: '裁剪图片',
              onCancel: () => {
                Message.info('取消上传');
                resolve(false);
                modal.close();
              },
              simple: false,
              content: (
                <Cropper
                  url={url}
                  file={file}
                  onOk={(file) => {
                    resolve(file);
                    modal.close();
                  }}
                  onCancel={() => {
                    resolve(false);
                    Message.info('取消上传');
                    modal.close();
                  }}
                />
              ),
              footer: null,
            });
        });
      }
    },[])

    return (
        <Upload
          imagePreview
          name="file"
          limit={multipleChoice? 9 : 1}
          action={`${config.api_url}/upload`}
          headers={{
            Authorization: `Bearer ${user.info.accessToken}`
          }}
          beforeUpload={beforeUpload}
          listType='picture-card'
          accept='image/*'
          {...props}
          fileList={store.list}
          onChange={(list) => {
            store.setList(list)
            if(onChange && JSON.stringify(store.value) !== JSON.stringify(values)){
              // 文件列表变更
              if(multipleChoice){
                // 多选
                onChange(store.value, store.list);
              }else {
                onChange(store.value[0], store.list[0]);
              }
            }
          }}
        />
    );
  })
};
  
export default UploadImg;